# Genera data/brands.json: grupos (perfil del dueño) + marcas que apuntan a cada grupo.
import json, os
A, V, OK = "Alta", "Verificar", "Verificado"
P = "Vanguard, BlackRock y otros fondos indexados (pasivos)"
NC = "No cotiza en bolsa"
G = {}
P_EN = "Vanguard, BlackRock and other passive index funds"
NC_EN = "Not publicly traded"

def g(id, empresa, controlador, pais, tipo, fondos="", gobierno="", nota="", confianza=A, fuente="", url="", ahorro=False, ahorro_fuente="", controlador_en="", nota_en="", fondos_en="", gobierno_en="", fuente_en=""):
    if not fondos_en:
        if fondos == P: fondos_en = P_EN
        elif fondos == NC or fondos == "No cotiza en bolsa": fondos_en = NC_EN
    G[id] = dict(empresa=empresa, controlador=controlador, pais=pais, tipo=tipo, fondos=fondos,
                 gobierno=gobierno, nota=nota, confianza=confianza, fuente=fuente, url=url, ahorro=ahorro, ahorro_fuente=ahorro_fuente,
                 controlador_en=controlador_en, nota_en=nota_en, fondos_en=fondos_en, gobierno_en=gobierno_en, fuente_en=fuente_en)

